import { apiClient } from '@/api/client';
import type { VendorProfile, VendorStatus } from '../types/vendor.types';
export interface OrganizationVendor extends VendorProfile { relationshipId: string; organizationId: string; relationshipStatus: VendorStatus | 'pending' | 'removed' }
export interface OrganizationVendorListParams { page?: number; limit?: number; search?: string; status?: OrganizationVendor['relationshipStatus']; serviceCategory?: string; sort?: 'createdAt' | '-createdAt' | 'name' | '-name' }
export interface OrganizationVendorListResponse { data: OrganizationVendor[]; pagination: { page: number; limit: number; total: number; pages: number } }
export const organizationVendorsApi = { list: (params?: OrganizationVendorListParams) => apiClient.get<OrganizationVendorListResponse>('/organizations/me/vendors', { params }), marketplace: (params?: Omit<OrganizationVendorListParams, 'status'>) => apiClient.get<OrganizationVendorListResponse>('/organizations/me/vendors/marketplace', { params }), get: (vendorId: string) => apiClient.get<OrganizationVendor>(`/organizations/me/vendors/${vendorId}`), requestRelationship: (vendorId: string) => apiClient.post(`/organizations/me/vendors/${vendorId}/request`), changeStatus: (vendorId: string, status: OrganizationVendor['relationshipStatus']) => apiClient.patch<OrganizationVendor>(`/organizations/me/vendors/${vendorId}/status`, { status }), facilityVendors: (facilityId: string) => apiClient.get<OrganizationVendor[]>(`/organizations/me/vendors/facilities/${facilityId}`), associateFacility: (facilityId: string, vendorId: string) => apiClient.post(`/organizations/me/vendors/facilities/${facilityId}/vendors/${vendorId}`), removeFacility: (facilityId: string, vendorId: string) => apiClient.delete(`/organizations/me/vendors/facilities/${facilityId}/vendors/${vendorId}`) };
